import{_ as t,c as a,o as s,a3 as o}from"./chunks/framework.Dokpd4od.js";const p=JSON.parse('{"title":"Blog","description":"","frontmatter":{},"headers":[],"relativePath":"master/website/blog/index.md","filePath":"master/website/blog/index.md","lastUpdated":1791902625000}'),l={name:"master/website/blog/index.md"};function r(i,e,n,h,d,g){return s(),a("div",null,e[0]||(e[0]=[o('<h1 id="blog" tabindex="-1">Blog <a class="header-anchor" href="#blog" aria-label="Permalink to &quot;Blog&quot;">​</a></h1><p>The blog is where you share news, tips and stories. Posts are sorted by date, grouped by category and labelled with tags. Visitors browse them at <code>/blog</code>.</p><blockquote><p><strong>In simple words:</strong> Pages stay still. Blog posts keep coming. Categories are the shelves and tags are the sticky notes.</p></blockquote><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Blog Posts, Categories and Tags need the <strong>Blogs</strong> plugin to be installed.</p></div><p>Open <code>Website → Blog Posts</code> or <code>Website → Configurations</code>.</p><h2 id="what-you-will-learn" tabindex="-1">What you will learn <a class="header-anchor" href="#what-you-will-learn" aria-label="Permalink to &quot;What you will learn&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What it teaches</th></tr></thead><tbody><tr><td><a href="./blog-posts.html">Blog posts</a></td><td>The list, the post form, banner, SEO, publish and what visitors see.</td></tr><tr><td><a href="./categories-and-tags.html">Categories and tags</a></td><td>Create the shelves and labels, archive them, and why a category may refuse to delete.</td></tr></tbody></table><h2 id="how-the-pieces-fit" tabindex="-1">How the pieces fit <a class="header-anchor" href="#how-the-pieces-fit" aria-label="Permalink to &quot;How the pieces fit&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Category (required) + Tags (optional) → Blog post → Publish → /blog</span></span></code></pre></div><ol><li>Create at least one category first. Every post needs one.</li><li>Write the post. Add tags if you like.</li><li>Click <strong>Publish</strong>. The post appears on <code>/blog</code>.</li></ol><h2 id="on-the-public-site" tabindex="-1">On the public site <a class="header-anchor" href="#on-the-public-site" aria-label="Permalink to &quot;On the public site&quot;">​</a></h2><p><code>/blog</code> shows <strong>Our Latest Posts</strong>. A row of pills lets visitors pick <strong>All</strong> or one category. A tag filter narrows the list. Nine posts show per page, newest first.</p><h2 id="example-content" tabindex="-1">Example content <a class="header-anchor" href="#example-content" aria-label="Permalink to &quot;Example content&quot;">​</a></h2><p>The sample site uses the categories <strong>The Knowledge Vault</strong>, <strong>The Flavor Journal</strong> and <strong>Beyond Borders Travel</strong>. It uses the tags <strong>Learn and Grow</strong>, <strong>Travel With Ease</strong> and <strong>Tech Savy Blogs</strong>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../">Website overview</a></li><li><a href="./../pages/">Pages</a></li><li><a href="./../settings/manage-contacts.html">Manage contacts</a></li></ul>',16)]))}const b=t(l,[["render",r]]);export{p as __pageData,b as default};
